custom_css:
.ca-companyname {
  display: table;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border: 1px solid #999;
  padding: 4px 18px;
  margin: 0 auto 14px;
  color: var(--ca-ink, #1a1a1a);
}

.web-form-container {
  --ca-ink: #1a1a1a;
  --ca-ink-soft: #444;
  --ca-line: #333;
  --ca-line-soft: #ccc;
  --ca-field-bg: #eef2f6;
  --ca-field-border: #c7d1db;
  --ca-label-w: 150px;
  max-width: 760px;
  margin: 0 auto;
  color: var(--ca-ink);
  font-family: Helvetica, Arial, sans-serif;
  font-size: 12.5px;
  line-height: 1.5;
}

.web-form-container .web-form-head {
  text-align: center;
}

.web-form-container .web-form-header {
  border-bottom: 1px solid var(--ca-line);
  padding-bottom: 16px;
  margin-bottom: 20px;
}

.web-form-container .web-form-head .title,
.web-form-container h1 {
  font-weight: 700;
  font-size: 22px;
  letter-spacing: normal;
  text-align: center;
  color: var(--ca-ink);
  margin-bottom: 0;
}

.web-form-container .web-form-introduction {
  display: none;
}

.web-form-wrapper .form-section {
  background: transparent;
  border: none;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
  margin-bottom: 22px;
}

.web-form-wrapper .section-head,
.web-form-wrapper .form-section .section-head {
  display: block;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ca-ink);
  padding-bottom: 4px;
  margin-bottom: 14px;
  border-bottom: 1px solid var(--ca-line-soft);
}

.web-form-wrapper .section-head::before {
  content: none;
}

.web-form-wrapper .form-group {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  gap: 8px !important;
  margin-bottom: 12px !important;
}

.web-form-wrapper .control-label {
  flex: 0 0 var(--ca-label-w) !important;
  max-width: var(--ca-label-w) !important;
  width: var(--ca-label-w) !important;
  font-weight: 700;
  font-size: 12.5px;
  color: var(--ca-ink);
  margin-bottom: 0 !important;
  white-space: normal;
}

.web-form-wrapper .control-input-wrapper {
  flex: 1 1 auto !important;
  min-width: 150px;
  width: auto !important;
}

.web-form-wrapper .form-control {
  border: 1px solid var(--ca-field-border);
  border-radius: 4px;
  background: var(--ca-field-bg);
  min-height: 30px;
}

.web-form-wrapper textarea.form-control {
  min-height: 56px;
}

.web-form-wrapper .form-control:focus {
  border-color: #8fa5b8;
  background: #fff;
  box-shadow: 0 0 0 2px rgba(143, 165, 184, 0.25);
  outline: none;
}

.web-form-wrapper .help-box {
  flex: 1 1 100%;
  color: var(--ca-ink-soft);
  font-size: 0.75rem;
  line-height: 1.4;
  margin: 2px 0 0 calc(var(--ca-label-w) + 8px);
}

.web-form-wrapper .frappe-control[data-fieldname="late_fee_percent"] .form-control[disabled],
.web-form-wrapper .frappe-control[data-fieldname="late_fee_percent"] .form-control:disabled {
  background: var(--ca-line-soft);
  color: var(--ca-ink-soft);
  cursor: not-allowed;
}

.ca-legal h3 {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ca-ink);
  margin: 14px 0 6px;
}

.ca-legal h3:first-child {
  margin-top: 0;
}

.ca-legal p {
  font-size: 12px;
  line-height: 1.55;
  color: var(--ca-ink-soft);
  margin: 0 0 10px;
}

.web-form-footer {
  border-top: 1px solid var(--ca-line-soft);
  padding-top: 1.25rem;
  margin-top: 0.5rem;
}

.web-form-footer .submit-btn {
  background: var(--ca-ink);
  border-color: var(--ca-ink);
  font-weight: 600;
  padding: 0.6rem 1.6rem;
  font-size: 0.9rem;
  border-radius: 4px;
}

.web-form-footer .submit-btn:hover {
  background: #000;
  border-color: #000;
}

.web-form-footer .discard-btn {
  border-radius: 4px;
  font-weight: 500;
  color: var(--ca-ink-soft);
  border-color: var(--ca-line-soft);
}

@media (max-width: 767px) {
  .web-form-container {
    max-width: 100%;
  }
  .web-form-wrapper .form-group {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 4px !important;
  }
  .web-form-wrapper .control-label {
    flex: none !important;
    max-width: none !important;
    width: auto !important;
  }
  .web-form-wrapper .help-box {
    margin-left: 0;
  }
}

/* Currency inputs show their symbol. Frappe only renders the symbol on
   read-only/formatted values, never inside an editable input, so the $ on
   this Currency field comes from here. */
.web-form-wrapper .frappe-control[data-fieldname="approved_limit"] .control-input {
  position: relative;
}

.web-form-wrapper .frappe-control[data-fieldname="approved_limit"] .control-input::before {
  content: "$";
  position: absolute;
  top: 50%;
  left: 10px;
  transform: translateY(-50%);
  line-height: 1;
  color: var(--ca-ink-soft);
  pointer-events: none;
  z-index: 2;
}

.web-form-wrapper .frappe-control[data-fieldname="approved_limit"] .form-control {
  /* infix_portal.css forces `padding: 8px 14px !important` on .form-control,
     .input-with-feedback and input[type="text"], so making room for the symbol
     has to outrank it. Without !important the $ lands on top of the digits. */
  padding-left: 26px !important;
}
